<?php
namespace Tests\Feature;
use App\Domain\Access;
use App\Sharing\SharingService;
use Illuminate\Foundation\Testing\DatabaseTransactions;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Str;
use Tests\TestCase;
final class ClassroomManagementTest extends TestCase {
 use DatabaseTransactions;
 private int $owner;private int $member;private int $admin;private int $course;private int $lesson;
 protected function setUp():void{parent::setUp();foreach(['owner','member','admin']as$role){$this->$role=DB::table('users')->insertGetId(['name'=>'测试 Ї Є','student_id'=>'000-'.Str::uuid(),'password'=>'unused','role'=>$role==='admin'?'admin':'user','must_change_password'=>false]);}$this->course=DB::table('courses')->insertGetId(['name'=>'Aerodynamics']);$this->lesson=DB::table('lessons')->insertGetId(['course_id'=>$this->course,'creator_id'=>$this->owner,'recorder_user_id'=>$this->owner,'name'=>'Second class','target_language'=>'zh','idempotency_key'=>(string)Str::uuid()]);SharingService::ensure($this->lesson);}
 public function test_member_can_rename_another_members_lesson_and_conflict_is_explicit():void{$this->withSession(['uid'=>$this->member])->patchJson('/api/lessons/'.$this->lesson,['name'=>'Другий урок','expected_version'=>1])->assertOk()->assertJsonPath('lesson.name','Другий урок');$this->withSession(['uid'=>$this->owner])->patchJson('/api/lessons/'.$this->lesson,['name'=>'overwrite','expected_version'=>1])->assertStatus(409)->assertJsonPath('code','lesson_version_conflict');self::assertSame(1,DB::table('audit')->where('lesson_id',$this->lesson)->where('action','lesson_renamed')->count());}
 public function test_guest_cannot_rename_or_delete():void{$this->patchJson('/api/lessons/'.$this->lesson,['name'=>'evil','expected_version'=>1])->assertStatus(401);$this->deleteJson('/api/admin/lessons/'.$this->lesson,['confirmed'=>true])->assertStatus(401);}
 public function test_empty_renaming_rejected_after_trim():void{$this->withSession(['uid'=>$this->member])->patchJson('/api/lessons/'.$this->lesson,['name'=>'   ','expected_version'=>1])->assertStatus(422);}
 public function test_stable_sort_and_filters_use_media_duration():void{DB::table('lessons')->where('id',$this->lesson)->update(['status'=>'ended','media_samples'=>16000]);foreach(['Bravo'=>48000,'Alpha'=>32000]as$name=>$samples)DB::table('lessons')->insert(['course_id'=>$this->course,'creator_id'=>$this->owner,'name'=>$name,'status'=>'ended','target_language'=>'zh','media_samples'=>$samples,'idempotency_key'=>(string)Str::uuid()]);$this->getJson('/api/courses/'.$this->course.'/lessons?sort=duration&direction=asc&status=ended')->assertOk()->assertJsonPath('lessons.0.id',$this->lesson)->assertJsonPath('total',3);$this->getJson('/api/courses/'.$this->course.'/lessons?search=ALP&sort=name&direction=desc')->assertOk()->assertJsonPath('lessons.0.name','Alpha')->assertJsonPath('total',1);}
 public function test_soft_delete_requires_ended_then_restore_preserves_records():void{$this->withSession(['uid'=>$this->admin,'reauth_until'=>time()+900])->deleteJson('/api/admin/lessons/'.$this->lesson,['confirmed'=>true])->assertStatus(409);DB::table('lessons')->where('id',$this->lesson)->update(['status'=>'ended']);$this->deleteJson('/api/admin/lessons/'.$this->lesson,['confirmed'=>true])->assertOk();$this->getJson('/api/lessons/'.$this->lesson)->assertStatus(404);self::assertNotNull(DB::table('lesson_shares')->where('lesson_id',$this->lesson)->first()->revoked_at);$this->postJson('/api/admin/lessons/'.$this->lesson.'/restore',['confirmed'=>true])->assertOk();$this->getJson('/api/lessons/'.$this->lesson)->assertOk();self::assertNotNull(DB::table('lesson_shares')->where('lesson_id',$this->lesson)->first()->revoked_at);}
 public function test_archived_course_history_readable_but_no_new_lesson():void{DB::table('lessons')->where('id',$this->lesson)->update(['status'=>'ended']);DB::table('courses')->where('id',$this->course)->update(['archived_at'=>now()]);$this->getJson('/api/lessons/'.$this->lesson)->assertOk();$this->withSession(['uid'=>$this->member])->postJson('/api/courses/'.$this->course.'/lessons',['name'=>'New','idempotency_key'=>(string)Str::uuid()])->assertStatus(404);}
 public function test_private_lesson_grant_does_not_grant_course_history():void{config(['session.driver'=>'database']);app('session')->forgetDrivers();DB::table('courses')->where('id',$this->course)->update(['guest_access'=>'link']);$share=DB::table('lesson_shares')->where('lesson_id',$this->lesson)->first();$token=\Illuminate\Support\Facades\Crypt::decryptString($share->token_encrypted);$this->get('/s/'.$token)->assertRedirect('/lessons/'.$this->lesson);$this->withCredentials()->withCookie(config('session.cookie'),session()->getId());$this->getJson('/api/lessons/'.$this->lesson)->assertOk();$this->getJson('/api/courses/'.$this->course.'/lessons')->assertStatus(403);}
}
